import { deckY, halfBreadth, stationZ, V } from "../../architecture/hull-geometry.js";

export function buildStern(d,ctx){
  const {part,box,beam,materials,V}=ctx;
  const stern=part('sternworks'),gallery=part('stern-gallery',stern),windows=part('stern-windows',stern);

  // The terminal hull station is now a broad transverse cut, not a pointed tail.
  // Its end cap is generated by hull-generator; this board makes the transom legible.
  const transomStation=1;
  const transomZ=stationZ(d,transomStation,0.52);
  const deck=deckY(d,transomStation);
  const width=Math.max(0.55,halfBreadth(d,transomStation)*1.92);
  const height=d.deckHeightUnits*0.58;
  const thickness=Math.max(0.065,d.beamUnits*0.014);
  const transom=box(stern,width,height,thickness,materials.hull,'sloop-square-transom');
  transom.position.set(0,deck-height*0.48,transomZ);

  // A restrained counter rail sits on the aft corners rather than forming a large gallery.
  for(const side of [-1,1]){
    const x=side*width*0.5;
    beam(
      gallery,
      V(x,deck+0.04,transomZ-thickness*0.65),
      V(x*0.96,deck+height*0.26,transomZ+thickness*0.18),
      0.032,
      materials.trim,
      'transom-quarter-rail'
    );
    for(let p=0;p<2;p++){
      const y=deck+height*(0.08+p*0.10);
      beam(
        gallery,
        V(x,y,transomZ-thickness*0.45),
        V(x*0.96,y+height*0.08,transomZ+thickness*0.18),
        0.021,
        materials.trim,
        'transom-baluster'
      );
    }
  }

  // Three small lights are more in scale with a working Caribbean sloop.
  const paneW=width*0.115,paneH=height*0.22;
  for(let n=0;n<3;n++){
    const x=(n-1)*width*0.30;
    const pane=box(windows,paneW,paneH,0.026,materials.glass,'transom-light');
    pane.position.set(x,deck-height*0.25,transomZ+thickness*0.57);
  }
}
